# ======================# Q2: confronto NFW vs core + PLOT# ======================import numpy as npimport matplotlib.pyplot as pltfrom scipy.integrate import quad# Costantir_sun = 8.33rho_sun = 0.3r_max = 60.0r_s = 24.42rho_s = 0.184deg_to_rad = np.pi / 180# Geometriadef r_gc(s, theta):    return np.sqrt(r_sun**2 + s**2 - 2*r_sun*s*np.cos(theta))def s_max(theta):    return r_sun*np.cos(theta) + np.sqrt(r_max**2 - (r_sun*np.sin(theta))**2)# Profilidef rho_nfw(r):    r = max(r, 1e-4)    return rho_s * (r_s / r) / (1 + r/r_s)**2def rho_core(r, r0=0.5):    return rho_s * (r_s / (r + r0)) / (1 + r/r_s)**2# J(theta)def J_theta(theta, profile="nfw"):    smax = s_max(theta)    def integrand(s):        r = r_gc(s, theta)        if profile == "nfw":            rho = rho_nfw(r)        else:            rho = rho_core(r)        return (rho / rho_sun)**2 / r_sun    s0 = r_sun*np.cos(theta)    return quad(integrand, 0, s0)[0] + quad(integrand, s0, smax)[0]# ===== Calcolo =====theta2 = 1 * deg_to_raddef J_bar(theta1, theta2, profile):    def integrand(theta):        return np.sin(theta) * J_theta(theta, profile)    num = 2*np.pi * quad(integrand, 1e-6, theta2)[0]    den = 2*np.pi * (np.cos(1e-6) - np.cos(theta2))    return num / denJ_nfw = J_bar(0, theta2, "nfw")J_core = J_bar(0, theta2, "core")print("=== Q2 ===")print("J NFW =", J_nfw)print("J core =", J_core)print("Ratio =", J_nfw / J_core)# ===== PLOT =====angles_deg = np.logspace(-3, 1, 60)angles = angles_deg * deg_to_radJ_nfw_vals = [J_theta(t, "nfw") for t in angles]J_core_vals = [J_theta(t, "core") for t in angles]plt.figure()plt.loglog(angles_deg, J_nfw_vals, label="NFW")plt.loglog(angles_deg, J_core_vals, label="Core (0.5 kpc)")plt.xlabel("theta (deg)")plt.ylabel("J(theta)")plt.title("NFW vs Core")plt.legend()plt.grid()plt.show()